def lenOfVDiagonal(grid: List[List[int]]) -> int:
    n = len(grid)
    m = len(grid[0])
    # Directions: 0:(1,1), 1:(1,-1), 2:(-1,-1), 3:(-1,1)
    # These are ordered such that (d+1)%4 is a 90-degree clockwise turn.
    dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

    # f[r][c][d_idx] stores the max length of a straight diagonal segment 
    # starting at (r, c) moving in direction d_idx following the sequence.
    f = [[[0] * 4 for _ in range(m)] for _ in range(n)]

    # Compute f using DP from the "end" of the grid towards the "start"
    for d_idx in range(4):
        dr, dc = dirs[d_idx]
        # Determine iteration order to ensure we compute children before parents
        r_range = range(n-1, -1, -1) if dr == 1 else range(n)
        c_range = range(m-1, -1, -1) if dc == 1 else range(m)
        if dr == 1 and dc == -1: r_range = range(n-1, -1, -1); c_range = range(m)
        if dr == -1 and dc == 1: r_range = range(n); c_range = range(m-1, -1, -1)
        # Correction for iteration order logic to ensure dependency is met:
        # If dr=1, nr > r. If dr=-1, nr < r. If dc=1, nc > c. If dc=-1, nc < c.
        if dr == 1 and dc == 1:
            for r in range(n-1, -1, -1):
                for c in range(m-1, -1, -1):
                    nr, nc = r + dr, c + dc
                    val = grid[r][c]
                    nxt = 2 if val == 1 else (0 if val == 2 else 2)
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == nxt:
                        f[r][c][d_idx] = 1 + f[nr][nc][d_idx]
                    else:
                        f[r][c][d_idx] = 1
        elif dr == 1 and dc == -1:
            for r in range(n-1, -1, -1):
                for c in range(m):
                    nr, nc = r + dr, c + dc
                    val = grid[r][c]
                    nxt = 2 if val == 1 else (0 if val == 2 else 2)
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == nxt:
                        f[r][c][d_idx] = 1 + f[nr][nc][d_idx]
                    else:
                        f[r][c][d_idx] = 1
        elif dr == -1 and dc == -1:
            for r in range(n):
                for c in range(m):
                    nr, nc = r + dr, c + dc
                    val = grid[r][c]
                    nxt = 2 if val == 1 else (0 if val == 2 else 2)
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == nxt:
                        f[r][c][d_idx] = 1 + f[nr][nc][d_idx]
                    else:
                        f[r][c][d_idx] = 1
        elif dr == -1 and dc == 1:
            for r in range(n):
                for c in range(m-1, -1, -1):
                    nr, nc = r + dr, c + dc
                    val = grid[r][c]
                    nxt = 2 if val == 1 else (0 if val == 2 else 2)
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == nxt:
                        f[r][c][d_idx] = 1 + f[nr][nc][d_idx]
                    else:
                        f[r][c][d_idx] = 1

    ans = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 1:
                ans = max(ans, 1)
                # Try all 4 initial directions from the '1'
                for d_idx in range(4):
                    dr, dc = dirs[d_idx]
                    curr_r, curr_c = r, c
                    path_len = 0

                    while True:
                        nr, nc = curr_r + dr, curr_c + dc
                        val = grid[curr_r][curr_c]
                        nxt_expected = 2 if val == 1 else (0 if val == 2 else 2)

                        if not (0 <= nr < n and 0 <= nc < m) or grid[nr][nc] != nxt_expected:
                            break

                        path_len += 1
                        curr_r, curr_c = nr, nc

                        # At every cell along the straight path, we can turn clockwise 90 degrees.
                        # The turn happens at (curr_r, curr_c).
                        d_next_idx = (d_idx + 1) % 4
                        dr_n, dc_n = dirs[d_next_idx]
                        tr, tc = curr_r + dr_n, curr_c + dc_n

                        # The sequence must continue from the turn.
                        val_at_turn = grid[curr_r][curr_c]
                        nxt_after_turn = 2 if val_at_turn == 1 else (0 if val_at_turn == 2 else 2)

                        # The total length is the current path + straight segment after turn.
                        # Note: f[tr][tc][d_next_idx] already includes the cell at (tr, tc).
                        if 0 <= tr < n and 0 <= tc < m and grid[tr][tc] == nxt_after_turn:
                            ans = max(ans, path_len + f[tr][tc][d_next_idx])
                        else:
                            # If no turn is possible or valid, the current straight length is a candidate.
                            ans = max(ans, path_len + 1)

    return ans
