        for char in words[i]:
            curr = curr[char]
            curr['count'] -= 1
            path.append(curr)

        # 搜尋最大深度 (利用 DFS)
        def dfs(node, depth):
            m_depth = depth if node.get('count', 0) >= k else 0
            for char in node:
                if char != 'count':
                    res = dfs(node[char], depth + 1)
                    if res > m_depth: m_depth = res
            return m_depth

        ans.append(dfs(trie, 0))

        # 還原
