from typing import List

def longestCommonPrefix(words: List[str], k: int) -> List[int]:
    n = len(words)
    if n - 1 < k:
        return [0] * n

    # Trie structure: char -> [children_dict, count, depth]
    trie = {}
    max_d = 0
    for w in words:
        curr = trie
        for d, char in enumerate(w, 1):
            if char not in curr:
                curr[char] = [{}, 0, d]
            curr[char][1] += 1
            curr = curr[char][0]
            if d > max_d:
                max_d = d

    nodes_at_depth = [0] * (max_d + 1)

    # Use iterative DFS to avoid recursion depth issues
    stack = [(trie, 0)]
    while stack:
        curr_dict, current_depth = stack.pop()
        for char in curr_dict:
            child = curr_dict[char]
            if child[1] >= k:
                nodes_at_depth[child[2]] += 1
            stack.append((child[0], child[2]))

    ans = [0] * n
    for i in range(n):
        w = words[i]
        curr = trie
        path_nodes = []
        for char in w:
            child = curr[char]
            path_nodes.append((curr, char, child))
            if child[1] == k:
                nodes_at_depth[child[2]] -= 1
            child[1] -= 1
            curr = child[0]

        res = 0
        for d in range(max_d, 0, -1):
            if nodes_at_depth[d] > 0:
                res = d
                break
        ans[i] = res

        # Restore path
        for parent_dict, char, child in reversed(path_nodes):
            child[1] += 1
            if child[1] == k:
                nodes_at_depth[child[2]] += 1

    return ans
